/* VÉRTICE GESTÃO V7 — camada incremental sobre a V6. Preserva a V6 e amplia CRM. */
const V7={docs:[],modelos:[],automacoes:[],versoes:[],opcoes:[],posvenda:[]};
function dedupeMessageModels(rows){
 const seen=new Set();
 return (rows||[]).filter(m=>{
   const key=`${String(m.canal||'').trim().toLowerCase()}|${String(m.nome||'').trim().toLowerCase()}`;
   if(seen.has(key))return false;
   seen.add(key);return true;
 });
}
const _v6load=load,_v6page=page,_v6dashboard=dashboard,_v6leads=leads,_v6clientes=clientes,_v6orcamentos=orcamentos,_v6relatorios=relatorios,_v6openClient=openClient,_v6openQuote=openQuote,_v6calcQuote=calcQuote,_v6toProduction=toProduction;
async function v7q(t){
 if(t==='orcamento_versoes'){let {data,error}=await sb.rpc('listar_orcamento_versoes_seguras');if(error){console.warn('V7',t,error.message);return[]}return Array.isArray(data)?data:[]}
 let {data,error}=await sb.from(t).select('*');if(error){console.warn('V7',t,error.message);return[]}return data||[]
}
load=async function(){await _v6load();[V7.docs,V7.modelos,V7.automacoes,V7.versoes,V7.opcoes,V7.posvenda]=await Promise.all(['cliente_documentos','mensagens_modelo','automacoes_crm','orcamento_versoes','orcamento_opcoes','pos_venda'].map(v7q));V7.modelos=dedupeMessageModels(V7.modelos);await seedV7Templates();V7.modelos=dedupeMessageModels(V7.modelos)}
page=function(name){$$('nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===name));let names={dashboard:'Dashboard',leads:'Leads / CRM',clientes:'Clientes',pipeline:'Pipeline',agenda:'Agenda / Retornos',orcamentos:'Orçamentos',producao:'Produção',materiais:'Materiais',custos:'Cadastros e custos',financeiro:'Financeiro',relatorios:'Relatórios',comunicacoes:'Comunicações',posvenda:'Pós-venda'};$('#pageTitle').textContent=names[name]||name;let fn={dashboard,leads,clientes,pipeline,agenda,orcamentos,producao,materiais,custos,financeiro,relatorios,comunicacoes,posvenda}[name]||dashboard;fn()}
function daysSince(v){if(!v)return 999;return Math.floor((Date.now()-new Date(v).getTime())/86400000)}
function leadTemp(l){let d=daysSince(l.ultima_interacao_em||l.criado_em);return d>=7?['cold','🔴 7+ dias']:d>=3?['warm','🟡 3–6 dias']:['hot','🟢 recente']}
function clientByCpfV7(raw,ignore=null){let d=digits(raw);return d?C.clientes.find(c=>digits(c.cpf)===d&&String(c.id)!==String(ignore))||null:null}
function duplicateClientModal(c){modal('Cliente já cadastrado',`<div class=notice><b>Já existe um cadastro correspondente a ${esc(c.nome)}.</b><p>Nenhum cadastro duplicado foi criado.</p></div>`,()=>{closeModal();client360(c.id)},'Abrir cliente existente')}
openClient=async function(id){let o=C.clientes.find(x=>x.id===id)||{};modal(id?'Editar cliente':'Novo cliente',`<div class=form-grid>${field('Nome','cn','text',o.nome||'')}${field('CPF','ccpf','text',o.cpf||'')}${field('Telefone','ctel','text',o.telefone||'')}${field('E-mail','ce','email',o.email||'')}${field('CEP','ccep','text',o.cep||'')}${field('Endereço','cend','text',o.endereco||'')}${field('Número','cnum','text',o.numero||'')}${field('Cidade','ccity','text',o.cidade||'')}${field('UF','cuf','text',o.uf||'')}</div>`,async()=>{let p={nome:v('cn'),cpf:cpf(v('ccpf')),telefone:phone(v('ctel')),email:v('ce'),cep:cep(v('ccep')),endereco:v('cend'),numero:v('cnum'),cidade:v('ccity'),uf:v('cuf').toUpperCase()};let dup;try{dup=await findExistingClient(p,id)}catch(err){return alert('Não foi possível conferir clientes existentes: '+err.message)}if(dup)return duplicateClientModal(dup);let r=id?await sb.from('clientes').update(p).eq('id',id):await sb.from('clientes').insert(p);if(r.error){if(r.error.code==='23505'){await load();let x=clientByCpfV7(p.cpf,id);return x?duplicateClientModal(x):alert('CPF já cadastrado.')}return alert(r.error.message)}closeModal();await load();clientes()});masks('c')}

dashboard=function(){let active=C.leads.filter(x=>x.status==='Ativo').length,pipe=C.leads.filter(x=>!['Fechado','Perdido'].includes(x.etapa)).reduce((s,x)=>s+Number(x.valor_potencial||0),0),ap=C.orcamentos.filter(x=>String(x.status).toLowerCase().includes('aprov')),approved=ap.reduce((s,x)=>s+Number(x.preco_final||0),0),quotes=C.orcamentos.length,won=ap.length,conv=quotes?won/quotes*100:0,avg=won?approved/won:0,cold=C.leads.filter(x=>leadTemp(x)[0]==='cold'&&!['Fechado','Perdido'].includes(x.etapa)).length,profit=ap.reduce((s,x)=>s+Number(x.valor_lucro||0),0);let origins={};C.leads.forEach(l=>{let k=l.origem||'Sem origem';origins[k]=(origins[k]||0)+1});let top=Object.entries(origins).sort((a,b)=>b[1]-a[1]).slice(0,5);$('#content').innerHTML=`<div class=cards><div class="card metric"><span>Leads ativos</span><b>${active}</b><i>${cold} esfriando</i></div><div class="card metric"><span>Pipeline</span><b>${money(pipe)}</b></div><div class="card metric"><span>Vendas aprovadas</span><b>${money(approved)}</b><i>${won} negócios</i></div><div class="card metric"><span>Conversão orçamentos</span><b>${conv.toFixed(1)}%</b></div><div class="card metric"><span>Ticket médio</span><b>${money(avg)}</b></div><div class="card metric"><span>Lucro previsto</span><b>${money(profit)}</b></div></div>${panel('Leads que precisam de atenção',table(['Cliente','Etapa','Temperatura','Próxima ação','Ações'],C.leads.filter(l=>leadTemp(l)[0]!=='hot'&&!['Fechado','Perdido'].includes(l.etapa)).slice(0,10).map(l=>`<tr><td>${esc(l.nome)}</td><td>${esc(l.etapa)}</td><td><span class="temp ${leadTemp(l)[0]}">${leadTemp(l)[1]}</span></td><td>${esc(l.proxima_acao||'Sem próximo passo')}</td><td><button class="btn small" onclick="openTask(${l.id})">Criar retorno</button></td></tr>`).join('')))}${panel('Origem dos leads',top.map(([k,n])=>`<div class=kpi-line><span>${esc(k)}</span><b>${n}</b></div>`).join(''))}`}
leads=function(){$('#content').innerHTML=panel('Leads e oportunidades',table(['Cliente','Origem','Projeto','Etapa','Classificação','Temperatura','Próxima ação','Valor','Ações'],C.leads.map(l=>{let t=leadTemp(l);return `<tr><td><b>${esc(l.nome)}</b><br><small>${esc(phone(l.telefone))}</small></td><td>${esc(l.origem||'')}</td><td>${esc(l.ambiente_interesse||'')}</td><td><span class=badge>${esc(l.etapa)}</span></td><td>${esc(classLabel(l.classificacao))}</td><td><span class="temp ${t[0]}">${t[1]}</span></td><td>${esc(l.proxima_acao||'Sem próximo passo')}</td><td>${money(l.valor_potencial)}</td><td><div class=toolbar><button class="btn small" onclick="openLead(${l.id})">Editar</button><button class="btn small" onclick="openQuote(${l.id})">Orçamento</button><button class="btn small" onclick="openInteractionV7(${l.id})">Contato</button><button class="btn small" onclick="openTask(${l.id})">Retorno</button><button class="btn small" onclick="chooseMessage('lead',${l.id})">Mensagem</button><button class="btn small" onclick="convertLead(${l.id})">Cliente</button></div></td></tr>`}).join('')),'<button class="btn gold" onclick="openLead()">+ Novo lead</button>')}
clientes=function(){$('#content').innerHTML=`<div class=searchbar><input placeholder="Pesquisar cliente por nome, CPF, telefone ou e-mail" oninput="filterRows(this.value)"></div>`+panel('Clientes',table(['Nome','CPF','Telefone','E-mail','Ações'],C.clientes.map(c=>`<tr><td><b>${esc(c.nome)}</b></td><td>${esc(cpf(c.cpf))}</td><td>${esc(phone(c.telefone))}</td><td>${esc(c.email||'')}</td><td><div class=toolbar><button class="btn small gold" onclick="client360(${c.id})">360º</button><button class="btn small" onclick="openClient(${c.id})">Editar</button><button class="btn small" onclick="chooseMessage('cliente',${c.id})">Mensagem</button><button class="btn small" onclick="openDocument(${c.id})">Documento</button></div></td></tr>`).join('')),'<button class="btn gold" onclick="openClient()">+ Cliente</button>')}
async function client360(id){let c=C.clientes.find(x=>x.id===id);if(!c)return;let qs=C.orcamentos.filter(o=>digits(o.cliente_cpf)===digits(c.cpf)||(o.cliente_nome||'').toLowerCase()===(c.nome||'').toLowerCase()),docs=V7.docs.filter(d=>d.cliente_id===id),pv=V7.posvenda.filter(x=>x.cliente_id===id),timeline=[...C.interacoes.filter(i=>i.cliente_id===id),...docs.map(d=>({criado_em:d.criado_em,titulo:'Documento: '+d.nome,descricao:d.tipo}))].sort((a,b)=>new Date(b.criado_em)-new Date(a.criado_em));$('#pageTitle').textContent='Cliente 360º';$('#content').innerHTML=`<div class=client-head><div><h2>${esc(c.nome)}</h2><span>${esc(phone(c.telefone))} • ${esc(c.email||'sem e-mail')} • ${esc(cpf(c.cpf))}</span></div><div class=toolbar><button class="btn gold" onclick="openQuoteForClient(${id})">+ Orçamento</button><button class=btn onclick="chooseMessage('cliente',${id})">Mensagem</button><button class=btn onclick="openDocument(${id})">+ Documento</button></div></div><div class=cards><div class="card metric"><span>Orçamentos</span><b>${qs.length}</b></div><div class="card metric"><span>Total orçado</span><b>${money(qs.reduce((s,x)=>s+Number(x.preco_final||0),0))}</b></div><div class="card metric"><span>Documentos</span><b>${docs.length}</b></div><div class="card metric"><span>Pós-venda</span><b>${pv.length}</b></div></div>${panel('Orçamentos',quoteTable(qs))}${panel('Documentos',docs.length?table(['Tipo','Arquivo','Data','Ações'],docs.map(d=>`<tr><td>${esc(d.tipo)}</td><td>${esc(d.nome)}</td><td>${dt(d.criado_em)}</td><td><button class="btn small" onclick="downloadDocument(${d.id})">Abrir</button></td></tr>`).join('')):'<p class=muted>Nenhum documento anexado.</p>','<button class="btn gold" onclick="openDocument('+id+')">+ Anexar</button>')}${panel('Linha do tempo',timeline.length?timeline.slice(0,30).map(x=>`<div class=timeline-item><b>${esc(x.titulo||x.tipo||'Interação')}</b><small>${dt(x.criado_em)}</small><p>${esc(x.descricao||'')}</p></div>`).join(''):'<p class=muted>Sem interações registradas.</p>')}`}
function openQuoteForClient(id){let c=C.clientes.find(x=>x.id===id);_v6openQuote();setTimeout(()=>{if(c)useClient(c.id)},0)}

orcamentos=function(){$('#content').innerHTML=`<div class=searchbar><input placeholder="Pesquisar orçamento por nº, cliente, projeto ou status" oninput="filterRows(this.value)"></div>`+panel('Orçamentos V7',table(['Nº','Cliente','Projeto','Custo','Lucro','Margem','Total','Status','Versão','Ações'],C.orcamentos.map(o=>{let m=Number(o.custo_producao)?Number(o.valor_lucro||0)/Number(o.custo_producao+Number(o.valor_lucro||0))*100:0;return `<tr><td>#${o.id}</td><td>${esc(o.cliente_nome||'')}</td><td>${esc(o.projeto||'')}</td><td>${money(o.custo_producao)}</td><td>${money(o.valor_lucro)}</td><td><span class="${m<20?'margin-alert':''}">${m.toFixed(1)}%</span></td><td><b>${money(o.preco_final)}</b></td><td><span class=badge>${esc(o.status)}</span></td><td>V${o.versao_atual||1}</td><td><div class=toolbar><button class="btn small" onclick="openQuote(null,${o.id})">Editar</button><button class="btn small" onclick="quoteVersions(${o.id})">Versões</button><button class="btn small" onclick="quoteOptions(${o.id})">Opções</button><button class="btn small" onclick="printQuote(${o.id})">Imprimir</button><button class="btn small" onclick="publicQuoteLink(${o.id})">Link</button><button class="btn small" onclick="markQuoteSent(${o.id})">Enviado</button><button class="btn small" onclick="approveQuote(${o.id})">Aprovar</button><button class="btn small" onclick="toProduction(${o.id})">Produção</button></div></td></tr>`}).join('')),'<button class="btn gold" onclick="openQuote()">+ Novo orçamento</button>')}
openQuote=async function(leadId=null,id=null){if(id){let o=C.orcamentos.find(x=>x.id===id);if(o)await snapshotQuote(o)}await _v6openQuote(leadId,id);let save=$('#saveModal');if(save){let orig=save.onclick;save.onclick=async e=>{let q=window.Q;if(q&&Number(q.margem)<20&&!confirm('A margem está abaixo de 20%. Deseja salvar mesmo assim?'))return;await orig(e)}}}
calcQuote=function(){_v6calcQuote();let q=window.Q;if(q&&$('#quoteSummary')){let pct=Number(q.margem)*100;if(pct<20)$('#quoteSummary').insertAdjacentHTML('afterbegin','<div class="margin-warning">⚠ Margem abaixo de 20%. Revise preço, desconto ou custos antes de enviar.</div>')}}
async function snapshotQuote(o){let vs=V7.versoes.filter(v=>v.orcamento_id===o.id),ver=Math.max(0,...vs.map(v=>v.versao||0))+1;if(vs.some(v=>v.preco_final==o.preco_final&&v.status==o.status))return;await sb.from('orcamento_versoes').insert({orcamento_id:o.id,versao:ver,preco_final:o.preco_final,custo_producao:o.custo_producao,valor_lucro:o.valor_lucro,margem_lucro:o.margem_lucro,status:o.status,dados:o})}
async function quoteVersions(id){await load();let a=V7.versoes.filter(x=>x.orcamento_id===id).sort((a,b)=>b.versao-a.versao);modal('Histórico de versões #'+id,a.length?table(['Versão','Data','Custo','Lucro','Total','Status'],a.map(x=>`<tr><td>V${x.versao}</td><td>${dt(x.criado_em)}</td><td>${money(x.custo_producao)}</td><td>${money(x.valor_lucro)}</td><td>${money(x.preco_final)}</td><td>${esc(x.status||'')}</td></tr>`).join('')):'<p class=muted>A primeira versão será registrada antes da próxima edição.</p>',closeModal,'Fechar')}
async function quoteOptions(id){let a=V7.opcoes.filter(x=>x.orcamento_id===id).sort((a,b)=>a.ordem-b.ordem);modal('Opções da proposta #'+id,`<p class=muted>Use opções como Essencial, Recomendado e Premium para apresentar alternativas sem reduzir apenas o preço.</p><div id=optRows>${a.map(optionRow).join('')}</div><button type=button class=btn onclick="addOptionRow()">+ Opção</button>`,async()=>{let rows=[...$$('#optRows .option-row')].map((r,i)=>({orcamento_id:id,nome:r.querySelector('.on').value,descricao:r.querySelector('.od').value,valor:Number(r.querySelector('.ov').value)||0,destaque:r.querySelector('.ok').checked,ordem:i})).filter(x=>x.nome);await sb.from('orcamento_opcoes').delete().eq('orcamento_id',id);if(rows.length){let z=await sb.from('orcamento_opcoes').insert(rows);if(z.error)return alert(z.error.message)}closeModal();await load();orcamentos()});if(!a.length){addOptionRow({nome:'Essencial'});addOptionRow({nome:'Recomendado',destaque:true});addOptionRow({nome:'Premium'})}}
function optionRow(x={}){return `<div class="option-row form-grid"><label>Nome<input class=on value="${esc(x.nome||'')}"></label><label>Valor<input class=ov type=number step=.01 value="${x.valor||0}"></label><label>Descrição<textarea class=od>${esc(x.descricao||'')}</textarea></label><label class=check><input class=ok type=checkbox ${x.destaque?'checked':''}> Recomendada</label><button type=button class="btn small danger" onclick="this.closest('.option-row').remove()">Remover</button></div>`}
function addOptionRow(x={}){$('#optRows').insertAdjacentHTML('beforeend',optionRow(x))}
async function markQuoteSent(id){let o=C.orcamentos.find(x=>x.id===id);await snapshotQuote(o);let r=await sb.from('orcamentos').update({status:'Enviado'}).eq('id',id);if(r.error)return alert(r.error.message);let lead=C.leads.find(x=>x.id===o.lead_id);if(lead){await sb.from('crm_leads').update({etapa:'Orçamento enviado',proxima_acao:'Confirmar recebimento do orçamento',proximo_contato_em:new Date(Date.now()+2*86400000).toISOString()}).eq('id',lead.id);await sb.from('crm_tarefas').insert({lead_id:lead.id,titulo:'Confirmar recebimento do orçamento #'+id,vencimento:new Date(Date.now()+2*86400000).toISOString(),prioridade:'Normal',status:'Pendente'})}await load();orcamentos()}
async function approveQuote(id){let o=C.orcamentos.find(x=>x.id===id);await snapshotQuote(o);let r=await sb.from('orcamentos').update({status:'Aprovado',aprovado_em:new Date().toISOString()}).eq('id',id);if(r.error)return alert(r.error.message);if(o.lead_id)await sb.from('crm_leads').update({etapa:'Fechado',status:'Convertido',proxima_acao:'Programar produção'}).eq('id',o.lead_id);await load();if(confirm('Orçamento aprovado. Programar produção agora?'))toProduction(id);else orcamentos()}

async function openInteractionV7(leadId){let l=C.leads.find(x=>x.id===leadId);modal('Registrar contato',`<div class=form-grid>${selectF('Canal','icanal',['WhatsApp','Telefone','Instagram','Facebook','E-mail','Presencial','Outro'],'WhatsApp')}${field('Assunto','iass','text','Contato com cliente')}${field('Próxima ação','inext','text','Retornar contato')}${field('Próximo contato','idate','datetime-local','')}</div><label>Registro do contato<textarea id=itxt></textarea></label>`,async()=>{let now=new Date().toISOString(),p={lead_id:leadId,tipo:v('icanal'),titulo:v('iass'),descricao:v('itxt')};let r=await sb.from('crm_interacoes').insert(p);if(r.error)return alert(r.error.message);await sb.from('crm_leads').update({ultima_interacao_em:now,proxima_acao:v('inext'),proximo_contato_em:v('idate')||null}).eq('id',leadId);if(v('idate'))await sb.from('crm_tarefas').insert({lead_id:leadId,titulo:v('inext')||'Retornar contato',vencimento:v('idate'),prioridade:'Normal',status:'Pendente'});closeModal();await load();leads()})}

const DEFAULT_MESSAGES=[
['Primeiro contato acolhedor','WhatsApp','Novo Lead','',`Olá, {{nome}}! Tudo bem? Aqui é da Vértice Marcenaria. Vi seu interesse em {{projeto}} e queria entender um pouco melhor o que você imagina para o ambiente. O que é mais importante para você nesse móvel: aproveitamento de espaço, visual, praticidade ou orçamento?`],
['Qualificação do projeto','WhatsApp','Qualificação','',`Oi, {{nome}}! Para conseguirmos pensar em uma solução que realmente faça sentido para você, posso te fazer algumas perguntas rápidas? Se puder, me envie medidas aproximadas do espaço, fotos do ambiente, uma referência do estilo que gosta e a faixa de investimento que pretende considerar.`],
['Orçamento enviado','WhatsApp','Orçamento enviado','',`Olá, {{nome}}! Finalizamos a proposta do seu projeto {{projeto}}. Preparei tudo considerando o que conversamos. Vou te enviar o orçamento e, quando conseguir olhar, me chama que explico qualquer detalhe e podemos ajustar o que for necessário.`],
['Follow-up 2 dias','WhatsApp','Follow-up','',`Oi, {{nome}}! Passando para confirmar se conseguiu visualizar a proposta que te enviei. Ficou alguma dúvida sobre o projeto, materiais, prazo ou forma de pagamento? Posso te ajudar a encontrar a melhor configuração.`],
['Follow-up sem pressão','WhatsApp','Follow-up','',`Olá, {{nome}}! Estou retomando nosso contato sobre {{projeto}}. Sei que móvel planejado é uma decisão importante e não quero te pressionar. Queria apenas saber se o projeto ainda está nos seus planos e se existe algum ponto da proposta que possamos rever juntos.`],
['Reativação de lead','WhatsApp','Adiado','',`Oi, {{nome}}! Há um tempo conversamos sobre {{projeto}} e lembrei do seu projeto. Ele ainda está nos seus planos? Se quiser, posso revisar a proposta e atualizar materiais, valores e possibilidades para você.`],
['Pós-venda 7 dias','WhatsApp','Pós-venda','',`Oi, {{nome}}! Passando para saber como está sendo a experiência com os móveis novos. Está tudo funcionando como esperado? Seu retorno é muito importante para nós.`],
['Indicação','WhatsApp','Pós-venda','',`Oi, {{nome}}! Ficamos felizes em participar do seu projeto. Se conhecer alguém planejando móveis sob medida, pode indicar a Vértice. Vamos cuidar do atendimento com o mesmo carinho e atenção.`],
['Envio de proposta por e-mail','E-mail','Orçamento enviado','Sua proposta Vértice — {{projeto}}',`Olá, {{nome}}!\n\nConforme conversamos, segue a proposta para {{projeto}}. Ela foi preparada considerando as necessidades e preferências levantadas no atendimento.\n\nCaso queira revisar algum item, material, prazo ou condição, responda este e-mail e ajustamos juntos.\n\nAtenciosamente,\nVértice Marcenaria`],
['Pós-venda por e-mail','E-mail','Pós-venda','Como ficou seu projeto Vértice?',`Olá, {{nome}}!\n\nGostaríamos de saber como está sua experiência após a entrega do projeto {{projeto}}. Se houver qualquer dúvida ou necessidade de orientação, estamos à disposição.\n\nObrigado por escolher a Vértice Marcenaria.`]
];
async function seedV7Templates(){if(V7.modelos.length)return;for(let x of DEFAULT_MESSAGES){let r=await sb.from('mensagens_modelo').insert({nome:x[0],canal:x[1],etapa:x[2],assunto:x[3],corpo:x[4]});if(r.error){console.warn('seed modelo',r.error.message);break}}if(!V7.modelos.length)V7.modelos=await v7q('mensagens_modelo')}
function fillTemplate(s,obj){let projeto=obj.ambiente_interesse||obj.projeto||'seu projeto';return String(s||'').replaceAll('{{nome}}',obj.nome||obj.cliente_nome||'').replaceAll('{{projeto}}',projeto).replaceAll('{{valor}}',money(obj.preco_final||obj.valor_potencial||0))}
function chooseMessage(kind,id){let obj=kind==='lead'?C.leads.find(x=>x.id===id):C.clientes.find(x=>x.id===id);if(!obj)return;let opts=V7.modelos.filter(x=>x.ativo!==false);modal('Mensagem para '+esc(obj.nome||''),`<label>Modelo<select id=msgmodel onchange="previewMessage('${kind}',${id})">${opts.map(x=>`<option value=${x.id}>${esc(x.canal+' — '+x.nome)}</option>`).join('')}</select></label><div id=msgpreview></div>`,()=>sendSelectedMessage(kind,id),'Abrir para enviar');previewMessage(kind,id)}
function previewMessage(kind,id){let obj=kind==='lead'?C.leads.find(x=>x.id===id):C.clientes.find(x=>x.id===id),m=V7.modelos.find(x=>String(x.id)===v('msgmodel'));if(!m)return;$('#msgpreview').innerHTML=`<div class=message-preview><b>${esc(m.assunto||m.nome)}</b><pre>${esc(fillTemplate(m.corpo,obj))}</pre></div>`}
function sendSelectedMessage(kind,id){let obj=kind==='lead'?C.leads.find(x=>x.id===id):C.clientes.find(x=>x.id===id),m=V7.modelos.find(x=>String(x.id)===v('msgmodel'));if(!m)return;if(m.canal==='WhatsApp'){let num=digits(obj.telefone);if(!num)return alert('Cliente sem telefone.');if(num.length<=11)num='55'+num;window.open(`https://wa.me/${num}?text=${encodeURIComponent(fillTemplate(m.corpo,obj))}`,'_blank')}else{if(!obj.email)return alert('Cliente sem e-mail.');location.href=`mailto:${encodeURIComponent(obj.email)}?subject=${encodeURIComponent(fillTemplate(m.assunto,obj))}&body=${encodeURIComponent(fillTemplate(m.corpo,obj))}`}}
function comunicacoes(){$('#content').innerHTML=panel('Modelos de WhatsApp e e-mail',table(['Nome','Canal','Etapa','Assunto','Ações'],V7.modelos.map(m=>`<tr><td><b>${esc(m.nome)}</b></td><td>${esc(m.canal)}</td><td>${esc(m.etapa||'')}</td><td>${esc(m.assunto||'')}</td><td><button class="btn small" onclick="editMessage(${m.id})">Editar</button></td></tr>`).join('')),'<button class="btn gold" onclick="editMessage()">+ Modelo</button>')+panel('Automações comerciais',table(['Regra','Evento','Atraso','Ação','Ativa'],V7.automacoes.map(a=>`<tr><td>${esc(a.nome)}</td><td>${esc(a.evento)}</td><td>${a.atraso_dias} dia(s)</td><td>${esc(a.acao)}</td><td>${a.ativo?'Sim':'Não'}</td></tr>`).join('')),'<button class="btn gold" onclick="editAutomation()">+ Automação</button>')}
async function editMessage(id){let o=V7.modelos.find(x=>x.id===id)||{};modal(id?'Editar modelo':'Novo modelo',`<div class=form-grid>${field('Nome','mnm','text',o.nome||'')}${selectF('Canal','mcan',['WhatsApp','E-mail'],o.canal||'WhatsApp')}${field('Etapa','met','text',o.etapa||'')}${field('Assunto','mass','text',o.assunto||'')}</div><label>Mensagem<textarea id=mcor rows=8>${esc(o.corpo||'')}</textarea></label><small>Variáveis: {{nome}}, {{projeto}}, {{valor}}</small>`,async()=>{let p={nome:v('mnm'),canal:v('mcan'),etapa:v('met'),assunto:v('mass'),corpo:v('mcor'),ativo:true},r=id?await sb.from('mensagens_modelo').update(p).eq('id',id):await sb.from('mensagens_modelo').insert(p);if(r.error)return alert(r.error.message);closeModal();await load();comunicacoes()})}
async function editAutomation(){modal('Nova automação',`<div class=form-grid>${field('Nome','an','text','Follow-up de orçamento')}${selectF('Evento','ae',['Orçamento enviado','Orçamento aprovado','Produção concluída','Lead sem contato'],'Orçamento enviado')}${field('Atraso em dias','ad','number',2)}${selectF('Ação','aa',['Criar tarefa','Sugerir WhatsApp','Sugerir e-mail'],'Criar tarefa')}${field('Título da tarefa','at','text','Retornar cliente')}</div>`,async()=>{let r=await sb.from('automacoes_crm').insert({nome:v('an'),evento:v('ae'),atraso_dias:n('ad'),acao:v('aa'),titulo_tarefa:v('at'),ativo:true});if(r.error)return alert(r.error.message);closeModal();await load();comunicacoes()})}

async function openDocument(clienteId){let c=C.clientes.find(x=>x.id===clienteId);modal('Anexar documento — '+esc(c?.nome||''),`<div class=form-grid>${selectF('Tipo','dtype',['Orçamento assinado','Contrato','Comprovante','Projeto 3D','Medição','Foto','Outro'],'Orçamento assinado')}${field('Observações','dobs','text','')}</div><label>Arquivo<input id=dfile type=file accept=".pdf,.jpg,.jpeg,.png,.webp,.doc,.docx"></label><small>Máximo 15 MB. O bucket é privado.</small>`,async()=>{let f=$('#dfile').files[0];if(!f)return alert('Selecione um arquivo.');if(f.size>15*1024*1024)return alert('Arquivo maior que 15 MB.');let {data:{user}}=await sb.auth.getUser(),path=`${user.id}/${clienteId}/${Date.now()}-${f.name.replace(/[^a-zA-Z0-9._-]/g,'_')}`,up=await sb.storage.from('cliente-documentos').upload(path,f,{upsert:false});if(up.error)return alert(up.error.message);let r=await sb.from('cliente_documentos').insert({cliente_id:clienteId,tipo:v('dtype'),nome:f.name,storage_path:path,tamanho:f.size,mime_type:f.type,observacoes:v('dobs')});if(r.error){await sb.storage.from('cliente-documentos').remove([path]);return alert(r.error.message)}closeModal();await load();client360(clienteId)},'Anexar')}
async function downloadDocument(id){let d=V7.docs.find(x=>x.id===id);if(!d)return;let {data,error}=await sb.storage.from('cliente-documentos').createSignedUrl(d.storage_path,120);if(error)return alert(error.message);window.open(data.signedUrl,'_blank')}

function posvenda(){$('#content').innerHTML=panel('Pós-venda e garantia',table(['Cliente','Entrega','Garantia','Status','Próximo contato','Ações'],V7.posvenda.map(p=>{let c=C.clientes.find(x=>x.id===p.cliente_id);return `<tr><td>${esc(c?.nome||'')}</td><td>${date(p.data_entrega)}</td><td>${date(p.garantia_ate)}</td><td><span class=badge>${esc(p.status)}</span></td><td>${date(p.proximo_contato)}</td><td><button class="btn small" onclick="editPostSale(${p.id})">Editar</button>${c?`<button class="btn small" onclick="chooseMessage('cliente',${c.id})">Mensagem</button>`:''}</td></tr>`}).join('')),'<button class="btn gold" onclick="editPostSale()">+ Pós-venda</button>')}
async function editPostSale(id){let o=V7.posvenda.find(x=>x.id===id)||{};modal(id?'Editar pós-venda':'Novo pós-venda',`<div class=form-grid><label>Cliente<select id=pvc><option value="">Selecione</option>${C.clientes.map(c=>`<option value=${c.id} ${c.id===o.cliente_id?'selected':''}>${esc(c.nome)}</option>`).join('')}</select></label>${field('Data de entrega','pve','date',o.data_entrega||'')}${field('Garantia até','pvg','date',o.garantia_ate||'')}${selectF('Status','pvs',['Acompanhar','Tudo certo','Assistência solicitada','Em garantia','Encerrado'],o.status||'Acompanhar')}${field('Próximo contato','pvp','date',o.proximo_contato||'')}</div><label>Observações<textarea id=pvo>${esc(o.observacoes||'')}</textarea></label>`,async()=>{let p={cliente_id:Number(v('pvc'))||null,data_entrega:v('pve')||null,garantia_ate:v('pvg')||null,status:v('pvs'),proximo_contato:v('pvp')||null,observacoes:v('pvo')},r=id?await sb.from('pos_venda').update(p).eq('id',id):await sb.from('pos_venda').insert(p);if(r.error)return alert(r.error.message);closeModal();await load();posvenda()})}

relatorios=function(){let origins={};C.leads.forEach(l=>{let k=l.origem||'Sem origem';origins[k]??={leads:0,quotes:0,sales:0,value:0};origins[k].leads++});C.orcamentos.forEach(o=>{let l=C.leads.find(x=>x.id===o.lead_id),k=l?.origem||'Sem origem';origins[k]??={leads:0,quotes:0,sales:0,value:0};origins[k].quotes++;if(String(o.status).toLowerCase().includes('aprov')){origins[k].sales++;origins[k].value+=Number(o.preco_final||0)}});let loss={};C.leads.filter(x=>x.etapa==='Perdido').forEach(x=>loss[x.motivo_perda||'Não informado']=(loss[x.motivo_perda||'Não informado']||0)+1);$('#content').innerHTML=panel('Conversão por origem',table(['Origem','Leads','Orçamentos','Vendas','Conversão','Receita'],Object.entries(origins).map(([k,x])=>`<tr><td><b>${esc(k)}</b></td><td>${x.leads}</td><td>${x.quotes}</td><td>${x.sales}</td><td>${x.leads?(x.sales/x.leads*100).toFixed(1):'0.0'}%</td><td>${money(x.value)}</td></tr>`).join('')))+panel('Motivos de perda',Object.entries(loss).length?Object.entries(loss).map(([k,n])=>`<div class=kpi-line><span>${esc(k)}</span><b>${n}</b></div>`).join(''):'<p class=muted>Sem perdas classificadas.</p>')}

function publicQuoteLink(id){let o=C.orcamentos.find(x=>x.id===id);if(!o?.public_token)return alert('Token público ainda não carregado. Atualize a página após executar o SQL V7.');let url=new URL('proposta.html',location.href);url.searchParams.set('t',o.public_token);navigator.clipboard?.writeText(url.href);modal('Link da proposta',`<p>Envie este link ao cliente para visualizar e aprovar a proposta:</p><input value="${esc(url.href)}" readonly onclick="this.select()"><p class=muted>O link foi copiado quando o navegador permitiu.</p>`,closeModal,'Fechar')}


/* ========================= V7.2 — arquivamento e exclusão segura ========================= */
let V72_CLIENT_FILTER='ativos',V72_LEAD_FILTER='ativos';
function v72Active(row){return row.arquivado!==true}
function v72Filter(rows,mode){return mode==='todos'?rows:mode==='arquivados'?rows.filter(x=>x.arquivado===true):rows.filter(v72Active)}
function v72FilterButtons(kind,mode){
 return `<div class="segmented">
 <button class="btn small ${mode==='ativos'?'gold':''}" onclick="${kind==='cliente'?'setClientFilter':'setLeadFilter'}('ativos')">Ativos</button>
 <button class="btn small ${mode==='arquivados'?'gold':''}" onclick="${kind==='cliente'?'setClientFilter':'setLeadFilter'}('arquivados')">Arquivados</button>
 <button class="btn small ${mode==='todos'?'gold':''}" onclick="${kind==='cliente'?'setClientFilter':'setLeadFilter'}('todos')">Todos</button></div>`;
}
function setClientFilter(x){V72_CLIENT_FILTER=x;clientes()}
function setLeadFilter(x){V72_LEAD_FILTER=x;leads()}
async function v72Audit(entidade,id,acao,detalhes={}){
 try{await sb.from('auditoria').insert({entidade,entidade_id:String(id),acao,detalhes})}catch(e){console.warn('auditoria',e)}
}
async function archiveClient(id,archive=true){
 let c=C.clientes.find(x=>x.id===id);if(!c)return;
 if(!confirm(`${archive?'Arquivar':'Reativar'} o cliente "${c.nome}"?`))return;
 let r=await sb.from('clientes').update({arquivado:archive,arquivado_em:archive?new Date().toISOString():null}).eq('id',id);
 if(r.error)return alert(r.error.message);
 await v72Audit('clientes',id,archive?'arquivado':'reativado',{nome:c.nome});
 await load();clientes();
}
async function archiveLead(id,archive=true){
 let l=C.leads.find(x=>x.id===id);if(!l)return;
 if(!confirm(`${archive?'Arquivar':'Reativar'} o lead "${l.nome}"?`))return;
 let r=await sb.from('crm_leads').update({arquivado:archive,arquivado_em:archive?new Date().toISOString():null}).eq('id',id);
 if(r.error)return alert(r.error.message);
 await v72Audit('crm_leads',id,archive?'arquivado':'reativado',{nome:l.nome});
 await load();leads();
}
async function v72Count(table,column,id){
 let r=await sb.from(table).select('id',{count:'exact',head:true}).eq(column,id);
 if(r.error){console.warn(table,r.error.message);return 0}
 return r.count||0;
}
async function deleteClientSafe(id){
 let c=C.clientes.find(x=>x.id===id);if(!c)return;
 let checks=await Promise.all([
  v72Count('orcamentos','cliente_id',id),v72Count('producao','cliente_id',id),
  v72Count('cliente_documentos','cliente_id',id),v72Count('pos_venda','cliente_id',id),
  v72Count('crm_interacoes','cliente_id',id),v72Count('crm_tarefas','cliente_id',id)
 ]);
 let labels=['orçamento(s)','produção(ões)','documento(s)','registro(s) de pós-venda','interação(ões)','tarefa(s)'];
 let deps=checks.map((n,i)=>n?`${n} ${labels[i]}`:'').filter(Boolean);
 if(deps.length)return alert(`Não é possível excluir "${c.nome}".\n\nExistem registros vinculados:\n• ${deps.join('\n• ')}\n\nArquive o cliente para preservar o histórico.`);
 let typed=prompt(`EXCLUSÃO PERMANENTE\n\nCliente: ${c.nome}\n\nDigite EXCLUIR para confirmar:`);
 if(typed!=='EXCLUIR')return;
 await v72Audit('clientes',id,'exclusao_permanente',{nome:c.nome,cpf:c.cpf||null});
 let r=await sb.from('clientes').delete().eq('id',id);
 if(r.error)return alert(r.error.message);
 await load();clientes();alert('Cliente excluído permanentemente.');
}
async function deleteLeadSafe(id){
 let l=C.leads.find(x=>x.id===id);if(!l)return;
 let [ints,tasks]=await Promise.all([v72Count('crm_interacoes','lead_id',id),v72Count('crm_tarefas','lead_id',id)]);
 if(ints||tasks)return alert(`Não é possível excluir "${l.nome}".\n\nExistem ${ints} interação(ões) e ${tasks} tarefa(s) vinculada(s).\nArquive o lead para preservar o histórico.`);
 let typed=prompt(`EXCLUSÃO PERMANENTE\n\nLead: ${l.nome}\n\nDigite EXCLUIR para confirmar:`);
 if(typed!=='EXCLUIR')return;
 await v72Audit('crm_leads',id,'exclusao_permanente',{nome:l.nome,telefone:l.telefone||null});
 let r=await sb.from('crm_leads').delete().eq('id',id);
 if(r.error)return alert(r.error.message);
 await load();leads();alert('Lead excluído permanentemente.');
}

/* V7.2 renderizações: preservam todas as ações V7 e acrescentam arquivo/exclusão/filtros */
leads=function(){
 let rows=v72Filter(C.leads,V72_LEAD_FILTER);
 $('#content').innerHTML=`<div class="v72-list-head">${v72FilterButtons('lead',V72_LEAD_FILTER)}</div>`+
 panel('Leads e oportunidades',table(['Cliente','Origem','Projeto','Etapa','Classificação','Temperatura','Próxima ação','Valor','Ações'],rows.map(l=>{let t=leadTemp(l);return `<tr class="${l.arquivado?'archived-row':''}"><td><b>${esc(l.nome)}</b>${l.arquivado?'<br><small>Arquivado</small>':''}<br><small>${esc(phone(l.telefone))}</small></td><td>${esc(l.origem||'')}</td><td>${esc(l.ambiente_interesse||'')}</td><td><span class=badge>${esc(l.etapa)}</span></td><td>${esc(classLabel(l.classificacao))}</td><td><span class="temp ${t[0]}">${t[1]}</span></td><td>${esc(l.proxima_acao||'Sem próximo passo')}</td><td>${money(l.valor_potencial)}</td><td><div class=toolbar><button class="btn small" onclick="openLead(${l.id})">Editar</button><button class="btn small" onclick="openQuote(${l.id})">Orçamento</button><button class="btn small" onclick="openInteractionV7(${l.id})">Contato</button><button class="btn small" onclick="openTask(${l.id})">Retorno</button><button class="btn small" onclick="chooseMessage('lead',${l.id})">Mensagem</button><button class="btn small" onclick="convertLead(${l.id})">Cliente</button><button class="btn small" onclick="archiveLead(${l.id},${!l.arquivado})">${l.arquivado?'Reativar':'Arquivar'}</button><button class="btn small danger" onclick="deleteLeadSafe(${l.id})">Excluir</button></div></td></tr>`}).join('')),'<button class="btn gold" onclick="openLead()">+ Novo lead</button>');
}
clientes=function(){
 let rows=v72Filter(C.clientes,V72_CLIENT_FILTER);
 $('#content').innerHTML=`<div class="v72-list-head"><div class=searchbar><input placeholder="Pesquisar cliente por nome, CPF, telefone ou e-mail" oninput="filterRows(this.value)"></div>${v72FilterButtons('cliente',V72_CLIENT_FILTER)}</div>`+
 panel('Clientes',table(['Nome','CPF','Telefone','E-mail','Ações'],rows.map(c=>`<tr class="${c.arquivado?'archived-row':''}"><td><b>${esc(c.nome)}</b>${c.arquivado?'<br><small>Arquivado</small>':''}</td><td>${esc(cpf(c.cpf))}</td><td>${esc(phone(c.telefone))}</td><td>${esc(c.email||'')}</td><td><div class=toolbar><button class="btn small gold" onclick="client360(${c.id})">360º</button><button class="btn small" onclick="openClient(${c.id})">Editar</button><button class="btn small" onclick="chooseMessage('cliente',${c.id})">Mensagem</button><button class="btn small" onclick="openDocument(${c.id})">Documento</button><button class="btn small" onclick="archiveClient(${c.id},${!c.arquivado})">${c.arquivado?'Reativar':'Arquivar'}</button><button class="btn small danger" onclick="deleteClientSafe(${c.id})">Excluir</button></div></td></tr>`).join('')),'<button class="btn gold" onclick="openClient()">+ Cliente</button>');
}


/* ========================= V8 — permissões efetivas + usuários ========================= */
const V8={perfil:null,permissoes:new Set(),usuarios:[],catalogoPermissoes:[],overrides:[]};
function can(codigo){return V8.perfil?.papel==='admin'||V8.permissoes.has(codigo)}
async function loadPermissions(){
 let {data,error}=await sb.rpc('minhas_permissoes');
 if(error){console.error('Permissões',error);V8.perfil=null;V8.permissoes=new Set();return false}
 V8.perfil=data||null;V8.permissoes=new Set(data?.permissoes||[]);return true;
}
async function loadUsersV8(){
 if(!can('usuarios.ver')){V8.usuarios=[];V8.catalogoPermissoes=[];V8.overrides=[];return}
 let [u,p,o]=await Promise.all([
  sb.from('perfis').select('user_id,nome,email,papel,ativo,criado_em').order('nome'),
  sb.from('permissoes').select('codigo,nome,modulo,descricao').order('modulo').order('nome'),
  sb.from('usuario_permissoes').select('user_id,permissao_codigo,permitido')
 ]);
 if(u.error)console.warn('usuarios',u.error.message);if(p.error)console.warn('permissoes',p.error.message);if(o.error)console.warn('overrides',o.error.message);
 V8.usuarios=u.data||[];V8.catalogoPermissoes=p.data||[];V8.overrides=o.data||[];
}
function ensureUsersNav(){
 let nav=document.querySelector('nav');if(!nav)return;
 let b=nav.querySelector('[data-page="usuarios"]');
 if(can('usuarios.ver')){if(!b){b=document.createElement('button');b.dataset.page='usuarios';b.textContent='Usuários e permissões';b.onclick=()=>page('usuarios');nav.appendChild(b)}}else b?.remove();
}
function v8AllowedPage(name){let map={dashboard:'dashboard.ver',leads:'crm.ver',pipeline:'crm.ver',clientes:'clientes.ver',agenda:'agenda.ver',orcamentos:'orcamentos.ver',producao:'producao.ver',materiais:'materiais.ver',custos:'configuracoes.ver',financeiro:'financeiro.ver',relatorios:'relatorios.ver',comunicacoes:'crm.ver',posvenda:'posvenda.ver',usuarios:'usuarios.ver'};return !map[name]||can(map[name])}
function applyPermissionUI(){
 let map={dashboard:'dashboard.ver',leads:'crm.ver',pipeline:'crm.ver',clientes:'clientes.ver',agenda:'agenda.ver',orcamentos:'orcamentos.ver',producao:'producao.ver',materiais:'materiais.ver',custos:'configuracoes.ver',financeiro:'financeiro.ver',relatorios:'relatorios.ver',comunicacoes:'crm.ver',posvenda:'posvenda.ver',usuarios:'usuarios.ver'};
 $$('nav button[data-page]').forEach(b=>{let c=map[b.dataset.page];if(c)b.style.display=can(c)?'':'none'});ensureUsersNav();
}
const _v8SessionUI=sessionUI;
sessionUI=async function(s){
 $('#login').classList.toggle('hidden',!!s);$('#app').classList.toggle('hidden',!s);
 if(!s){V8.perfil=null;V8.permissoes=new Set();return}
 if(!await loadPermissions()){console.error('Não foi possível validar permissões. Sessão mantida, mas módulos protegidos permanecem bloqueados.');$('#pageTitle').textContent='Configuração de acesso pendente';$('#content').innerHTML='<div class="panel"><div class="panel-body"><h3>Não foi possível validar suas permissões</h3><p>O login foi realizado, mas o banco de dados não possui a configuração de permissões esperada pelo sistema. Sua sessão foi preservada. É necessário restaurar a estrutura de usuários e permissões do projeto correto.</p></div></div>';return}
 await load();await loadUsersV8();applyPermissionUI();
 let first=['dashboard','leads','clientes','orcamentos','agenda','producao','materiais','financeiro','relatorios'].find(v8AllowedPage)||'dashboard';let savedPage='';try{savedPage=sessionStorage.getItem('vertice:page:'+s.user.id)||''}catch(e){console.warn('Navegação sem armazenamento de sessão',e)}page(savedPage&&v8AllowedPage(savedPage)&&['dashboard','leads','clientes','pipeline','agenda','orcamentos','producao','materiais','custos','financeiro','relatorios','comunicacoes','posvenda','usuarios'].includes(savedPage)?savedPage:first);
}
const _v8Page=page;
page=async function(name){
 if(!v8AllowedPage(name)){ $('#pageTitle').textContent='Acesso restrito';$('#content').innerHTML='<div class="panel"><div class="panel-body"><p>Seu usuário não possui permissão para este módulo.</p></div></div>';return }
 if(name==='usuarios'){usuariosV8()}else{_v8Page(name);applyPermissionUI()}
 try{const uid=(await sb.auth.getSession()).data.session?.user?.id;if(uid)sessionStorage.setItem('vertice:page:'+uid,name)}catch(e){console.warn('Não foi possível guardar a página atual',e)}
}

/* Orçamentos: custos/lucro/margem aparecem somente para quem possui as permissões. */
quoteTable=function(arr){
 let showCost=can('orcamentos.ver_custos'),showProfit=can('orcamentos.ver_lucro');
 let headers=['Nº','Cliente','Projeto'];if(showCost)headers.push('Custo interno');if(showProfit)headers.push('Lucro');headers.push('Total cliente','Status','Ações');
 return table(headers,arr.map(o=>{let cells=`<td>#${o.id}</td><td>${esc(o.cliente_nome||'')}</td><td>${esc(o.projeto||'')}</td>`;if(showCost)cells+=`<td>${money(o.custo_producao)}</td>`;if(showProfit)cells+=`<td>${money(o.valor_lucro)}</td>`;let actions=[];if(can('orcamentos.editar'))actions.push(`<button class="btn small" onclick="openQuote(null,${o.id})">Editar</button>`);actions.push(`<button class="btn small" onclick="printQuote(${o.id})">Imprimir</button>`);if(can('producao.criar'))actions.push(`<button class="btn small" onclick="toProduction(${o.id})">Produção</button>`);if(can('orcamentos.excluir'))actions.push(`<button class="btn small danger" onclick="deleteQuote(${o.id})">Excluir</button>`);return `<tr>${cells}<td><b>${money(o.preco_final)}</b></td><td><span class=badge>${esc(o.status)}</span></td><td><div class=toolbar>${actions.join('')}</div></td></tr>`}).join(''));
}
orcamentos=function(){
 let showCost=can('orcamentos.ver_custos'),showProfit=can('orcamentos.ver_lucro'),canMargin=can('orcamentos.alterar_margem');
 let headers=['Nº','Cliente','Projeto'];if(showCost)headers.push('Custo');if(showProfit)headers.push('Lucro');if(canMargin)headers.push('Margem');headers.push('Total','Status','Versão','Ações');
 let rows=C.orcamentos.map(o=>{let cells=`<td>#${o.id}</td><td>${esc(o.cliente_nome||'')}</td><td>${esc(o.projeto||'')}</td>`;if(showCost)cells+=`<td>${money(o.custo_producao)}</td>`;if(showProfit)cells+=`<td>${money(o.valor_lucro)}</td>`;if(canMargin){let m=Number(o.margem_lucro||0);cells+=`<td><span class="${m<20?'margin-alert':''}">${m.toFixed(1)}%</span></td>`}let a=[];if(can('orcamentos.editar'))a.push(`<button class="btn small" onclick="openQuote(null,${o.id})">Editar</button>`);a.push(`<button class="btn small" onclick="quoteVersions(${o.id})">Versões</button>`,`<button class="btn small" onclick="quoteOptions(${o.id})">Opções</button>`,`<button class="btn small" onclick="printQuote(${o.id})">Imprimir</button>`,`<button class="btn small" onclick="publicQuoteLink(${o.id})">Link</button>`);if(can('orcamentos.editar'))a.push(`<button class="btn small" onclick="markQuoteSent(${o.id})">Enviado</button>`,`<button class="btn small" onclick="approveQuote(${o.id})">Aprovar</button>`);if(can('producao.criar'))a.push(`<button class="btn small" onclick="toProduction(${o.id})">Produção</button>`);if(can('orcamentos.excluir'))a.push(`<button class="btn small danger" onclick="deleteQuote(${o.id})">Excluir</button>`);let primary=can('orcamentos.editar')?a.shift():null;let menu=`<details class="quote-action-menu"><summary class="btn small">Mais ações ▾</summary><div class="quote-action-dropdown">${a.join('')}</div></details>`;return `<tr>${cells}<td><b>${money(o.preco_final)}</b></td><td><span class=badge>${esc(o.status)}</span></td><td>V${o.versao_atual||1}</td><td><div class="quote-action-group">${primary||''}${menu}</div></td></tr>`}).join('');
 let add=can('orcamentos.criar')?'<button class="btn gold" onclick="openQuote()">+ Novo orçamento</button>':'';
 $('#content').innerHTML=`<div class=searchbar><input placeholder="Pesquisar orçamento por nº, cliente, projeto ou status" oninput="filterRows(this.value)"></div>`+panel('Orçamentos',table(headers,rows),add);
}
const _v8OpenQuote=openQuote;
openQuote=async function(leadId=null,id=null){
 if(id&&!can('orcamentos.editar'))return alert('Seu usuário não possui permissão para editar orçamentos.');
 if(!id&&!can('orcamentos.criar'))return alert('Seu usuário não possui permissão para criar orçamentos.');
 /* O formulário atual calcula a proposta a partir de custos internos. Não expomos esses dados a perfis sem permissão. */
 if(!can('orcamentos.ver_custos'))return alert('Este perfil pode acessar orçamentos, mas o editor de cálculo interno exige permissão de custos. A leitura comercial continua protegida.');
 await _v8OpenQuote(leadId,id);
 if(!can('orcamentos.alterar_margem')){let el=$('#qmargem');if(el){el.disabled=true;el.title='Sem permissão para alterar margem'}}
}
const _v8DeleteQuote=deleteQuote;
deleteQuote=async function(id){if(!can('orcamentos.excluir'))return alert('Sem permissão para excluir orçamentos.');return _v8DeleteQuote(id)}

