dashboard=function(){_v8Dashboard();if(!can('orcamentos.ver_lucro'))$$('#content .card.metric').forEach(c=>{if((c.querySelector('span')?.textContent||'').toLowerCase().includes('lucro'))c.remove()})}
const _v8Relatorios=relatorios;
